const DICT_LIGHT = {
    "Morning Rose": [[255,140,160], [255,80,100], [160,30,60]],
    "Golden Nave": [[255,200,80], [220,130,30], [140,70,15]],
    "Cobalt Chancel": [[80,130,255], [30,70,220], [15,30,140]],
    "Emerald Cloister": [[100,255,130], [30,200,70], [15,120,35]],
    "Obsidian Twilight": [[60,40,80], [30,20,50], [15,10,25]],
    "Blinding Supernova": [[255,255,255], [255,240,200], [220,200,255]]
};

const DICT_DENSITY = {
    "Intact Rose Window": 24,
    "Hairline Fissures": 36,
    "Branching Faults": 52,
    "Spiderweb Fractures": 75,
    "Shattered Mosaic": 110,
    "Crystalline Powder": 150
};

const DICT_CAME = {
    "Heavy Iron Came": {w: 6, jit: 0},
    "Tarnished Ribbon": {w: 4.5, jit: 0.8},
    "Trembling Grooves": {w: 3.5, jit: 1.8},
    "Quivering Seams": {w: 2.5, jit: 3.2},
    "Volt Spasms": {w: 1.8, jit: 5.5},
    "Molten Silver Rupture": {w: 1.2, jit: 9.0}
};

const DICT_LEAK = {
    "Subdued Wax Candle": {b: 0.05, p: 1},
    "Slanted Sunbeams": {b: 0.15, p: 2},
    "Bleeding Edges": {b: 0.30, p: 3},
    "Flaring Fractures": {b: 0.45, p: 3.5},
    "Blown Highlights": {b: 0.65, p: 4.5},
    "Solar Flare Breach": {b: 1.0, p: 6.0}
};

const DICT_SPLINTERS = {
    "Settled Dust": 0,
    "Stray Flakes": 30,
    "Drifting Embers": 65,
    "Spalling Swarm": 105,
    "Glass Squall": 150,
    "Glass Tempest": 200
};

let pts = [];
let splinters = [];

function clipPoly(polyX, polyY, len, pAx, pAy, pBx, pBy) {
    let nx = pBx - pAx, ny = pBy - pAy;
    let midX = (pAx + pBx) * 0.5, midY = (pAy + pBy) * 0.5;
    let outX = [], outY = [];
    for (let i = 0; i < len; i++) {
        let j = (i + 1) % len;
        let p1x = polyX[i], p1y = polyY[i];
        let p2x = polyX[j], p2y = polyY[j];
        let d1 = (p1x - midX) * nx + (p1y - midY) * ny;
        let d2 = (p2x - midX) * nx + (p2y - midY) * ny;

        if (d1 <= 0) {
            outX.push(p1x);
            outY.push(p1y);
        }
        if (d1 * d2 < 0) {
            let t = d1 / (d1 - d2);
            outX.push(p1x + t * (p2x - p1x));
            outY.push(p1y + t * (p2y - p1y));
        }
    }
    for (let i = 0; i < outX.length; i++) {
        polyX[i] = outX[i];
        polyY[i] = outY[i];
    }
    return outX.length;
}

p.setup = function() {
    p.createCanvas(800, 800);
    for (let i = 0; i < 150; i++) {
        pts.push({
            x: p.random(-50, 850),
            y: p.random(-50, 850),
            vx: p.random(-0.3, 0.3),
            vy: p.random(-0.3, 0.3),
            cIdx: p.floor(p.random(3))
        });
    }
    for (let i = 0; i < 200; i++) {
        splinters.push({
            x: p.random(800),
            y: p.random(800),
            vx: p.random(-2, 2),
            vy: p.random(-3, -1),
            life: p.random(1)
        });
    }
};

p.draw = function() {
    const vLight = p.getSynthVar('cathedral_light') || "Morning Rose";
    const vDen = p.getSynthVar('fracture_density') || "Intact Rose Window";
    const vCame = p.getSynthVar('lead_came') || "Heavy Iron Came";
    const vLeak = p.getSynthVar('light_leak') || "Subdued Wax Candle";
    const vSplint = p.getSynthVar('shiver_splinters') || "Settled Dust";

    const colors = DICT_LIGHT[vLight];
    const maxPts = DICT_DENSITY[vDen];
    const came = DICT_CAME[vCame];
    const leak = DICT_LEAK[vLeak];
    const splintCount = DICT_SPLINTERS[vSplint];

    p.background(15);
    p.drawingContext.globalCompositeOperation = 'source-over';

    let edgesX1 = [], edgesY1 = [], edgesX2 = [], edgesY2 = [];

    p.noStroke();
    for (let i = 0; i < maxPts; i++) {
        pts[i].x += pts[i].vx;
        pts[i].y += pts[i].vy;

        if (pts[i].x < -50 || pts[i].x > 850) pts[i].vx *= -1;
        if (pts[i].y < -50 || pts[i].y > 850) pts[i].vy *= -1;

        let px = [0, 800, 800, 0];
        let py = [0, 0, 800, 800];
        let plen = 4;

        for (let j = 0; j < maxPts; j++) {
            if (i === j) continue;
            plen = clipPoly(px, py, plen, pts[i].x, pts[i].y, pts[j].x, pts[j].y);
            if (plen === 0) break;
        }

        if (plen > 2) {
            let c = colors[pts[i].cIdx];
            p.fill(c[0], c[1], c[2]);
            p.beginShape();
            for (let k = 0; k < plen; k++) {
                p.vertex(px[k], py[k]);
                let kNext = (k + 1) % plen;
                edgesX1.push(px[k]);
                edgesY1.push(py[k]);
                edgesX2.push(px[kNext]);
                edgesY2.push(py[kNext]);
            }
            p.endShape(p.CLOSE);
        }
    }

    p.strokeCap(p.ROUND);
    p.strokeJoin(p.ROUND);
    p.stroke(0);
    p.strokeWeight(came.w);
    p.beginShape(p.LINES);
    for (let i = 0; i < edgesX1.length; i++) {
        let jitX1 = p.random(-came.jit, came.jit);
        let jitY1 = p.random(-came.jit, came.jit);
        let jitX2 = p.random(-came.jit, came.jit);
        let jitY2 = p.random(-came.jit, came.jit);
        p.vertex(edgesX1[i] + jitX1, edgesY1[i] + jitY1);
        p.vertex(edgesX2[i] + jitX2, edgesY2[i] + jitY2);
    }
    p.endShape();

    p.drawingContext.globalCompositeOperation = 'lighter';

    if (leak.b > 0) {
        p.strokeWeight(leak.p * 2);
        p.stroke(255, 255, 255, leak.b * 255);
        p.beginShape(p.LINES);
        for (let i = 0; i < edgesX1.length; i += 2) {
            p.vertex(edgesX1[i], edgesY1[i]);
            p.vertex(edgesX2[i], edgesY2[i]);
        }
        p.endShape();
    }

    if (splintCount > 0 && edgesX1.length > 0) {
        p.noStroke();
        for (let i = 0; i < splintCount; i++) {
            let s = splinters[i];
            s.x += s.vx;
            s.y += s.vy;
            s.life -= 0.015;

            if (s.life <= 0) {
                let eIdx = p.floor(p.random(edgesX1.length));
                s.x = edgesX1[eIdx];
                s.y = edgesY1[eIdx];
                s.life = 1.0;
            }
            let alpha = s.life * 255;
            p.fill(255, 220, 150, alpha);
            p.circle(s.x, s.y, 2.5);
        }
    }
};
